/* Ink & Chai service worker — generated by generate_site.py, do not edit. */
const VERSION = '3ce02fb26159';
const PAGES  = 'iac-pages-'  + VERSION;   // HTML, so a revisit works offline
const ASSETS = 'iac-assets-' + VERSION;   // css/js/fonts, all content-hashed
const IMAGES = 'iac-img-v1';              // covers; survives releases, LRU-capped
const OFFLINE_URL = '/offline/';
const PRECACHE = ["/offline/", "/manifest.json", "/images/icon-192.png", "/css/app-shell-1ab7a601.css", "/js/app-shell-228cb1b7.js"];

const PAGE_LIMIT  = 60;
const IMAGE_LIMIT = 150;

// Paths the worker must never answer from its own cache, because a stale copy
// would be worse than no copy: the admin panel, anything in the payment path,
// and every function endpoint. Returning undefined from fetch() leaves these
// entirely to the browser.
const NEVER = /^\/(admin|checkout|refund-upi|\.netlify)(\/|$)/;

self.addEventListener('install', event => {
  event.waitUntil((async () => {
    const cache = await caches.open(ASSETS);
    // allSettled, not all: one 404 in the list must not abandon the install and
    // leave the client with no worker at all.
    await Promise.allSettled(PRECACHE.map(url => cache.add(new Request(url, { cache: 'reload' }))));
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    const keep = new Set([PAGES, ASSETS, IMAGES]);
    for (const key of await caches.keys()) {
      if (key.startsWith('iac-') && !keep.has(key)) await caches.delete(key);
    }
    if (self.registration.navigationPreload) {
      await self.registration.navigationPreload.enable();
    }
    await self.clients.claim();
  })());
});

// Cache API keys() returns insertion order, so the oldest entry is the first.
async function trim(cacheName, limit) {
  const cache = await caches.open(cacheName);
  const keys = await cache.keys();
  for (let i = 0; i < keys.length - limit; i++) await cache.delete(keys[i]);
}

// Network first. The shop's prices, stock and delivery promises change during
// the day, so a page is only ever served from cache when the network failed.
async function navigation(event) {
  const request = event.request;
  try {
    const preloaded = await event.preloadResponse;
    const response = preloaded || await fetch(request);
    // Only plain URLs are stored. A query string means a filtered category, a
    // search, or a payment return like ?paid=1 — that last one fires a Google
    // Ads conversion, and replaying it from cache would invent a sale.
    if (response && response.ok && !new URL(request.url).search) {
      const cache = await caches.open(PAGES);
      await cache.put(request, response.clone());
      trim(PAGES, PAGE_LIMIT);
    }
    return response;
  } catch (err) {
    const cached = await caches.match(request, { ignoreSearch: true });
    if (cached) return cached;
    const offline = await caches.match(OFFLINE_URL);
    if (offline) return offline;
    throw err;
  }
}

// Content-hashed filenames, so a hit can be served without revalidating: a
// changed file arrives under a new name. The background fetch is what picks up
// the handful of assets whose names are stable.
async function asset(request) {
  const cache = await caches.open(ASSETS);
  const hit = await cache.match(request);
  const fresh = fetch(request).then(response => {
    if (response && response.ok) cache.put(request, response.clone());
    return response;
  }).catch(() => null);
  return hit || await fresh || Response.error();
}

async function image(request) {
  const cache = await caches.open(IMAGES);
  const hit = await cache.match(request);
  if (hit) return hit;
  try {
    const response = await fetch(request);
    if (response && response.ok) {
      await cache.put(request, response.clone());
      trim(IMAGES, IMAGE_LIMIT);
    }
    return response;
  } catch (err) {
    return hit || Response.error();
  }
}

self.addEventListener('fetch', event => {
  const request = event.request;
  if (request.method !== 'GET') return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;
  if (NEVER.test(url.pathname)) return;

  if (request.mode === 'navigate') { event.respondWith(navigation(event)); return; }

  const kind = request.destination;
  if (kind === 'image') { event.respondWith(image(request)); return; }
  if (kind === 'style' || kind === 'script' || kind === 'font') { event.respondWith(asset(request)); }
});
